INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(42311, 'Job 40:24', 'Job', 40, 24, 'څوک دا د کُنډو سره راوچتولے شى، يا يې څوک په پوزه کښې د قابو کولو دپاره پېزوان اچولے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job40_verse_24.mp3', '', 1761754199, 1761754199),
(42312, 'Songofsongs 6:1', 'Songofsongs', 6, 1, 'ستا جانان چرته لاړونه، په ټولو پېغلو کښې ښائسته جينۍ؟ ستا جانان چرته تلے دېنه؟ چې مونږ تا سره د هغۀ تلاش وکړونه؟ محبوبه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_1.mp3', '', 1761754199, 1761754199),
(42313, 'Songofsongs 6:2', 'Songofsongs', 6, 2, 'زما جانان خپل باغ ته راغلے دېنه، خپل د خوشبويانو کټ ته، چې خپله رمه په باغونو کښې وڅروينه، او د لاله ګلونه ترې نه راټول کړينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_2.mp3', '', 1761754199, 1761754199),
(42314, 'Songofsongs 6:3', 'Songofsongs', 6, 3, 'جانان زما او زۀ د جانان يمه، هغه چې د لاله په ګلونو کښې مزې کوينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_3.mp3', '', 1761754199, 1761754199),
(42315, 'Songofsongs 6:4', 'Songofsongs', 6, 4, 'زما محبوبې، تۀ لکه د تِرضاه د ښار په شان ښائسته ينه. آو، لکه د يروشلم په شان ښائسته ينه، او په يو ځل ليدو دې ما نه زړګے وړے دېنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_4.mp3', '', 1761754199, 1761754199),
(42316, 'Songofsongs 6:5', 'Songofsongs', 6, 5, 'سترګې دې ما نه واړوه، ځکه چې زۀ يې بې‌وسه کړے يمه. ستا زلفى وَل وَل لکه د چېلو د رمو په شان دينه، چې د جِلعاد د غرۀ نه لاندې راکوزيږينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_5.mp3', '', 1761754199, 1761754199),
(42317, 'Songofsongs 6:6', 'Songofsongs', 6, 6, 'ستا غاښونه د سپينو ګډو په شان دينه، چې تازه ترې نه وړۍ اخوا شوې وينه، او تازه لمبولے شوے وينه. هر يو غاښ دې د بل سره جوړه دېنه، يو هم کنډم شوے نۀ دېنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_6.mp3', '', 1761754199, 1761754199),
(42318, 'Songofsongs 6:7', 'Songofsongs', 6, 7, 'ستا اننګى د نقاب شاته لکه د ګلابى انار ځليږينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_7.mp3', '', 1761754199, 1761754199),
(42319, 'Songofsongs 6:8', 'Songofsongs', 6, 8, 'په شپېتو مَلِکو او په اتيا وينځو کښې او په بې‌شمېره پېغلو کښې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_8.mp3', '', 1761754199, 1761754199),
(42320, 'Songofsongs 6:9', 'Songofsongs', 6, 9, 'خو زۀ به بيا هم خپله ګوګوشتکه خوښومه، زما کامله مينه، د خپلې مور ډېره خوښه ده نه، او د هغه چا ډېره نيازبينه چا چې زيږولې ده نه. پېغلې هغه وينى او د هغې صِفت کوينه، تر دې چې شهزادګۍ او شاهى وينځې د هغې د صِفت سندرې وائينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_9.mp3', '', 1761754199, 1761754199),
(42321, 'Songofsongs 6:10', 'Songofsongs', 6, 10, '”دا څوک ده چې لکه د سحر د رڼا په شان راوچتيږينه، لکه د سپوږمۍ په شان ښائسته، او د نمر په شان ځليږينه، او په يو ځل ليدو دې ما نه زړګے وړے دېنه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_10.mp3', '', 1761754199, 1761754199),
(42322, 'Songofsongs 6:11', 'Songofsongs', 6, 11, 'زۀ د غوزانو باغ ته لاړمه او وادۍ ته د ګلونو د غوټو سيل ته لاړمه، د انګورو د ځيلو راټوکېدل ووينمه او چې انارو ګلونه کړى دى کۀ نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_11.mp3', '', 1761754199, 1761754199),
(42323, 'Songofsongs 6:12', 'Songofsongs', 6, 12, 'زۀ په خپل ځان نۀ پوهېدمه، او د عشق نه رپېدمه لکه چې په شاهى ګاډۍ کښې سور يمه ښځې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_12.mp3', '', 1761754199, 1761754199),
(42324, 'Songofsongs 6:13', 'Songofsongs', 6, 13, 'واپس راشه، مونږ ته راواپس شه، اے د شولم پېغلې. واپس راشه، واپس راشه چې مونږ تا دوباره وګورونه. محبوب تاسو د شولم دې پېغلې ته ولې ګورئينه کله چې هغه د ګډېدونکو د دوه صفونو په مينځ کښې ډېره ښائسته ګډيږينه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs6_verse_13.mp3', '', 1761754199, 1761754199),
(42325, 'Isaiah 25:1', 'Isaiah', 25, 1, 'ای څښتنه، ته یې خدای زما زه به کومه درناوی ستا او ثنا او صفت به کوم ستا د نامه ځکه تا کړي دي ډېر عجیبه کارونه هغه څه چې پلان کړي تا پخوا وو په وفادارۍ دې رسولي هغه سرته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_1.mp3', '', 1761754199, 1761754199),
(42326, 'Isaiah 25:2', 'Isaiah', 25, 2, 'تا بدل کړي دي ښارونه کنډوالو باندې او ورانې کړې دې دي ټینګې کلاګانې کومې ماڼۍ چې جوړې کړې وې پردو قومونو هغه شوې ورانې د تل دپاره داسې چې بیا به جوړې نه شي هېڅکله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_2.mp3', '', 1761754199, 1761754199),
(42327, 'Isaiah 25:3', 'Isaiah', 25, 3, 'نو په دې خاطر به وکړي ثنا او صفت ستا د نړۍ د تکړه قومونو خلک او خلک به تا نه وېره وکړي د ظالمو قومونو په ښارونو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_3.mp3', '', 1761754199, 1761754199),
(42328, 'Isaiah 25:4', 'Isaiah', 25, 4, 'ځکه چې ته د مصیبت په وخت کې یې ساتونکی د غریبو او بې وسه خلکو تا ورکړې ده پناه هغوی ته د توفانونو وخت کې او ورکړی دې دی سیوری د سوځوونکې ګرمۍ په وخت کې د توفان په شان دی پوکی د ظالمانو چې لګیږي په دېوال', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_4.mp3', '', 1761754199, 1761754199),
(42329, 'Isaiah 25:5', 'Isaiah', 25, 5, 'لکه ګرمي د صحرا چې وچوي ځمکه خو ای څښتنه، غلي کوې ته اوازونه د پردو قومونو داسې لکه ورېځ چې سړوي ډېره ګرمي نو غلې کوې ته همدارنګه سندره د ظالمو خلکو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_5.mp3', '', 1761754199, 1761754199),
(42330, 'Isaiah 25:6', 'Isaiah', 25, 6, 'مطلق قادر څښتن به د صهیون په غره باندې د نړۍ ټولو قومونو ته د خوندورو خوراکونو او د انګورو د ښو زړو شرابو مېلمستیا تیاره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_6.mp3', '', 1761754199, 1761754199),
(42331, 'Isaiah 25:7', 'Isaiah', 25, 7, 'دلته به هغه د غم څادر لېرې کړي چې په ټولو خلکو باندې هوار دی او د قومونو څخه به هغه کفن لېرې کړي چې په هغوی باندې پروت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_7.mp3', '', 1761754199, 1761754199),
(42332, 'Isaiah 25:8', 'Isaiah', 25, 8, 'څښتن تعالی به د تل دپاره مرګ لېرې کړي! هغه به د هرچا د سترګو اوښکې وچې کړي او د خپلو خلکو هغه رسوایي او بې عزتي چې هغوی په ټوله نړۍ کې ورسره مخامخ دي، لېرې کړي. دا په خپله څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_8.mp3', '', 1761754199, 1761754199),
(42333, 'Isaiah 25:9', 'Isaiah', 25, 9, 'په هغه ورځ به خلک داسې وایي: «وګورئ، هغه زمونږ خدای دی چې ورته سترګې په لاره وو او مونږ یې ژغورلي یو. هغه څښتن دی چې مونږ د هغه نه هیله لرله، نو په دې خاطر چې هغه مونږ ژغوري، باید د خوشحالۍ جشن جوړ کړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_9.mp3', '', 1761754199, 1761754199),
(42334, 'Isaiah 25:10', 'Isaiah', 25, 10, 'څښتن به د صهیون د غره ساتنه کوي، خو د موآب خلک به داسې تر پښو لاندې شي لکه بوس چې په ډېران کې تر پښو لاندې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_10.mp3', '', 1761754199, 1761754199),
(42335, 'Isaiah 25:11', 'Isaiah', 25, 11, 'هغوی به د خپلې ژغورنې په خاطر د لامبوزنو په شان لاس او پښې وهي، خو څښتن به د هغوی مهارت له منځه یوسي او غرور به یې مات کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_11.mp3', '', 1761754199, 1761754199),
(42336, 'Isaiah 25:12', 'Isaiah', 25, 12, 'څښتن به د موآب جنګي کلاګانې چې لوړ لوړ دېوالونه لري، راوغورځوي او د خاورو سره به یې خاورې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah25_verse_12.mp3', '', 1761754199, 1761754199),
(42337, 'Isaiah 12:1', 'Isaiah', 12, 1, 'داسې ورځ راروانه ده چې تاسو به دا سندره ووایئ: «ای څښتنه، زه کوم شکرګزاري ستا! که څه هم ته راته په قهر وې اوس نور په قهر نه یې او ماته تسلي راکوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah12_verse_1.mp3', '', 1761754199, 1761754199),
(42338, 'Isaiah 12:2', 'Isaiah', 12, 2, 'ګورئ، چې خدای زما ژغورونکی دی زه به هغه باندې توکل کوم او نور به نه وېرېږم ځکه څښتن خدای زه قوي کړمه د هغه په هکله زه سندره وایم زه یې ژغورلی یمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah12_verse_2.mp3', '', 1761754199, 1761754199),
(42339, 'Isaiah 12:3', 'Isaiah', 12, 3, 'څنګه چې تږي خوشحالیږي د کوهي په اوبو همداسې کړي به خوشحالي هغوی په هغه وخت چې خدای وژغوري خپل قوم»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah12_verse_3.mp3', '', 1761754199, 1761754199),
(42340, 'Isaiah 12:4', 'Isaiah', 12, 4, 'هغه ورځ راروانه ده چې تاسو به دا سندره ووایئ: «کړئ د څښتن شکر ادا! وکړئ دعا یې په نوم! هغه چې څه کړي بیان یې کړئ ټولو قومونو ته هغوی ته ووایئ چې څومره ډک دی د هغه نوم د جلال نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah12_verse_4.mp3', '', 1761754199, 1761754199),
(42341, 'Isaiah 12:5', 'Isaiah', 12, 5, 'څښتن ته ووایئ سندره د هغه د پر جلاله کارنامو په خاطر پرېږدئ چې نړۍ ټوله د دې څخه خبره شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah12_verse_5.mp3', '', 1761754199, 1761754199),
(42342, 'Isaiah 12:6', 'Isaiah', 12, 6, 'ای اوسېدونکو د صهیون په لوړ اواز ووهئ چیغې او سندرې د خوښۍ ووایئ ځکه ډېر لوی دی سپېڅلی خدای د اسراییلو او اوسیږي ستاسو منځ کې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah12_verse_6.mp3', '', 1761754199, 1761754199),
(42343, 'Ezekiel 8:1', 'Ezekiel', 8, 1, 'زمونږ د جلاوطنۍ په شپږم کال، د شپږمې میاشتې په پنځمه ورځ زه په خپل کور کې د یهودا د مشرانو سره ناست وم. ناڅاپه د څښتن تعالی قوت په ما باندې نازل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_1.mp3', '', 1761754199, 1761754199),
(42344, 'Ezekiel 8:2', 'Ezekiel', 8, 2, 'ما وکتل او په رویا کې مې د انسان په شان یو شکل ولیده. بدن یې د ملا نه ښکته د اور د لمبو په شان ښکاره کېده او د ملا نه پورته د یو ځلېدونکي فلز په شان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_2.mp3', '', 1761754199, 1761754199),
(42345, 'Ezekiel 8:3', 'Ezekiel', 8, 3, 'وروسته بیا هغه یو شی چې د لاس په شان ؤ، را‌اوږد کړ او زه یې د ویښتانو څخه ونیولم. په دې وخت کې په رویا کې د خدای روح اسمان ته پورته کړم او زه یې په اورشلیم کې د څښتن د کور د دنننۍ حوېلۍ د شمالي دروازې خولې ته بوتلم. هلته یو بت ؤ چې خدای یې ډېر په قهر کړ او د هغه غیرت یې راوپاراوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_3.mp3', '', 1761754199, 1761754199),
(42346, 'Ezekiel 8:4', 'Ezekiel', 8, 4, 'نو هلته مې د اسراییلو د خدای جلال ولیده چې د هغې رویا په شان ؤ چې په دره کې مې لیدلې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_4.mp3', '', 1761754199, 1761754199),
(42347, 'Ezekiel 8:5', 'Ezekiel', 8, 5, 'بیا څښتن ماته وویل: «ای فاني انسانه، اوس شمال خواته وګوره.» نو ما هغې خواته وکتل او د دروازې شمال خواته مې د هغه بت د قربانۍ ځای ولیده چې د خدای غیرت یې راپارولی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_5.mp3', '', 1761754199, 1761754199),
(42348, 'Ezekiel 8:6', 'Ezekiel', 8, 6, 'څښتن ماته وویل: «ای فاني انسانه، ته وینې چې د اسراییلو قوم په څه کارونو باندې اخته دی؟ ګوره چې هغوی د کرکې وړ کارونه کوي او دا د دې سبب ګرځي چې زه د خپل سپېڅلي ځای څخه لېرې شم. خو ته به د دې څخه نور هم زیات د کرکې وړ کارونه ووینې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_6.mp3', '', 1761754199, 1761754199),
(42349, 'Ezekiel 8:7', 'Ezekiel', 8, 7, 'هغه زه د دنننۍ حوېلۍ د دروازې خولې ته بوتلم او په دېوال کې یې راته یو سوری راوښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_7.mp3', '', 1761754199, 1761754199),
(42350, 'Ezekiel 8:8', 'Ezekiel', 8, 8, 'هغه ماته وویل: «ای فاني انسانه، دا سوری لوی کړه.» او ما هغه سوری لوی کړ او هلته مې یوه دروازه ولیدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_8.mp3', '', 1761754199, 1761754199),
(42351, 'Ezekiel 8:9', 'Ezekiel', 8, 9, 'هغه راته وویل: «دننه لاړ شه او وګوره چې هغوی څنګه ناوړه او د کرکې وړ کارونه په دې ځای کې سرته رسوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_9.mp3', '', 1761754199, 1761754199),
(42352, 'Ezekiel 8:10', 'Ezekiel', 8, 10, 'نو زه دننه ورغلم او ومې لیدل چې په دېوالونو باندې د خزندو، ناپاکو حیواناتو او د هغو ټولو بتانو نقشونه چې اسراییلیانو ورته عبادت کاوه، ویستل شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_10.mp3', '', 1761754199, 1761754199),
(42353, 'Ezekiel 8:11', 'Ezekiel', 8, 11, 'د اسراییلو د قوم اویا مشران د هغو په مخکې هلته ولاړ وو چې په هغو کې د شافان زوی یازنیا هم شامل ؤ. هر یو په خپلو لاسونو کې د خوشبویۍ د سوځولو لوښی نیولی ؤ او د هغه نه د خوشبویۍ لوګی پورته کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_11.mp3', '', 1761754199, 1761754199),
(42354, 'Ezekiel 8:12', 'Ezekiel', 8, 12, 'څښتن زما څخه پوښتنه وکړه: «ای فاني انسانه، ایا تا لیدلي دي چې د اسراییلو ټول مشران په خپله کوټه کې په پټه د خپل بت عبادت کوي؟ هغوی داسې وایي: ‹څښتن مونږ نه ویني، ځکه چې هغه دا هېواد پریښی دی.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_12.mp3', '', 1761754199, 1761754199),
(42355, 'Ezekiel 8:13', 'Ezekiel', 8, 13, 'بیا څښتن وویل: «ته به د دې څخه وروسته د دې نه هم ډېر د کرکې وړ کارونه چې هغوی یې کوي، ووینې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_13.mp3', '', 1761754199, 1761754199),
(42356, 'Ezekiel 8:14', 'Ezekiel', 8, 14, 'نو هغه زه د څښتن د کور د شمالي دروازې خولې ته بوتلم او هلته یې ښځې راته وښودلې چې ناستې وې او د خپل خدای تموز په مرګ یې ژړا کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_14.mp3', '', 1761754199, 1761754199),
(42357, 'Ezekiel 8:15', 'Ezekiel', 8, 15, 'هغه پوښتنه وکړه: «ای فاني انسانه، ایا ته دا وینې؟ خو ته به د دې څخه وروسته د دې نه هم ډېر ناوړه او د کرکې وړ کارونه ووینې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_15.mp3', '', 1761754199, 1761754199),
(42358, 'Ezekiel 8:16', 'Ezekiel', 8, 16, 'نو بیا هغه زه د څښتن د کور دنننۍ حوېلۍ ته بوتلم. هلته د څښتن د کور د ننوتلو دروازې ته نژدې د قربانۍ د ځای او برنډې ترمنځ پنځه ویشت سړي ولاړ وو. هغوی د عبادت ځای ته شاګانې اړولې وې او خپل مخونه یې ختیځ خواته اړولي وو او لمر ته یې عبادت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_16.mp3', '', 1761754199, 1761754199),
(42359, 'Ezekiel 8:17', 'Ezekiel', 8, 17, 'څښتن ماته وویل: «ای فاني انسانه، ایا ته دا وینې؟ ایا دا لازمه ده چې د یهودا قوم دا د کرکې وړ کارونه تر‌سره کړي، په ټول هېواد کې ظلم او زیاتی خپور کړي او زما قهر او غضب نور هم راوپاروي؟ هغوی ته وګوره چې څنګه په بې‌شرمۍ زما سپکاوی کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_17.mp3', '', 1761754199, 1761754199),
(42360, 'Ezekiel 8:18', 'Ezekiel', 8, 18, 'نو له دې امله به په هغوی باندې خپل غضب نازل کړم. زه به هغوی ته د مینې په سترګه ونه ګورم او په هغوی باندې به هېڅ رحم ونه کړم. هغوی به چیغې وهي او ماته به په ډېر لوړ اواز زارۍ کوي، خو زه به ورته غوږ ونه نیسم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel8_verse_18.mp3', '', 1761754199, 1761754199),
(42361, 'Jonah 2:1', 'Jonah', 2, 1, 'د ماهي د ګېډې څخه یونس خپل څښتن خدای ته دعا وکړه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah2_verse_1.mp3', '', 1761754199, 1761754199),
(42362, 'Jonah 2:2', 'Jonah', 2, 2, 'په خپل تکلیف کې مې ای څښتنه تاته غږ وکړ او تا ځواب راکړ د مړو د نړۍ د ډېر ژور ځای څخه ما فریاد وکړ د مرستې په خاطر او تا واورېده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah2_verse_2.mp3', '', 1761754199, 1761754199),
(42363, 'Jonah 2:3', 'Jonah', 2, 3, 'تا زه ژورو اوبو ته ورګوزار کړم د بحیرې تل ته او سیلاب راګېر کړم او زما په سر تېرې شوې ستا زورورې څپې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah2_verse_3.mp3', '', 1761754199, 1761754199),
(42364, 'Jonah 2:4', 'Jonah', 2, 4, 'نو ما وویل چې زه شړل شوی یمه ستا له نظره څخه خو بیا به هم زه سترګې واړوم ستا د سپېڅلي کور خواته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah2_verse_4.mp3', '', 1761754199, 1761754199),
(42365, 'Jonah 2:5', 'Jonah', 2, 5, 'اوبه راباندې راغلې او ساه اخیستی نه شم او شوې راچاپېرې له ما د بحیرې اوبه زما د سر څخه راتاو شول د بحیرې واښه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah2_verse_5.mp3', '', 1761754199, 1761754199),
(42366, 'Jonah 2:6', 'Jonah', 2, 6, 'ورسېدم زه دغرونو بېخ ته لاندې ځمکې تل ترتله راګېر کړمه زه خو تا راووېستم ژوندی د مرګ له کندې څخه ای څښتنه زما خدایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah2_verse_6.mp3', '', 1761754199, 1761754199),
(42367, 'Jonah 2:7', 'Jonah', 2, 7, 'کله چې وتله زما ساه نو ته مې رایاد کړلې څښتنه او زما دعا ورسېدله تاته ستا سپېڅلي کور کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah2_verse_7.mp3', '', 1761754199, 1761754199),
(42368, 'Jonah 2:8', 'Jonah', 2, 8, 'چې بې‌ارزښته بتانو ته کړي عبادت څوک هغوی پریښی خپل امید دی د خدای د تلپاتې مینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah2_verse_8.mp3', '', 1761754199, 1761754199),
(42369, 'Jonah 2:9', 'Jonah', 2, 9, 'خو د شکرګزارۍ په کولو سره زه به وړاندې کړمه تاته قرباني او ما چې منلی نذر، زه به یې ورکړمه راځي خلاصون د څښتن له خوا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah2_verse_9.mp3', '', 1761754199, 1761754199),
(42370, 'Jonah 2:10', 'Jonah', 2, 10, 'بیا څښتن په ماهي باندې امر وکړ او ماهي یونس وچې ځمکې ته ورګوزار کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jonah2_verse_10.mp3', '', 1761754199, 1761754199),
(42371, 'Hosea 12:1', 'Hosea', 12, 1, 'څښتن وایي: «هغه کارونه چې د اسراییلو خلک یې د سهار نه تر ماښامه پورې کوي، هغه بې‌ګټې او خرابوونکي کارونه دي. په هغوی کې خیانت او ظلم زیاتې زیاتیږي. هغوی د آشوریانو سره تړونونه کوي او مصریانو ته د مرستې په خاطر د زیتون تېل ورکوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_1.mp3', '', 1761754199, 1761754199),
(42372, 'Hosea 12:2', 'Hosea', 12, 2, 'څښتن د یهودا خلک ملامتوي او اسراییلو ته د هغه د خلکو د عملونو په سبب سزا ورکوي. د هغوی څخه به د خپلو کارونو بدل واخیستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_2.mp3', '', 1761754199, 1761754199),
(42373, 'Hosea 12:3', 'Hosea', 12, 3, 'د هغوی نیکه یعقوب د خپل غبرګوني ورور عیسو سره چې دواړه لا د مور په خېټه کې وو، جګړه وکړه. کله چې یعقوب لوی شو، هغه د خدای سره هم جنګ وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_3.mp3', '', 1761754199, 1761754199),
(42374, 'Hosea 12:4', 'Hosea', 12, 4, 'هغه د فرښتې سره غېږه ونیوله او په هغې باندې بریالی شو. هغه وژړل او د برکت دپاره یې سوال وکړ. په بیت‌ییل کې خدای زمونږ د نیکه یعقوب سره مخامخ شو او د هغه سره یې خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_4.mp3', '', 1761754199, 1761754199),
(42375, 'Hosea 12:5', 'Hosea', 12, 5, 'څښتن هغه مطلق قادر خدای دی چې د هغه په نوم باندې عبادت کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_5.mp3', '', 1761754199, 1761754199),
(42376, 'Hosea 12:6', 'Hosea', 12, 6, 'نو اوس ای د یعقوب اولادې، په خپل خدای باندې توکل کوئ او د هغه خواته راوګرځئ. وفادار او عادل اوسئ او په صبر سره خپل خدای ته انتظار کوئ چې هغه څه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_6.mp3', '', 1761754199, 1761754199),
(42377, 'Hosea 12:7', 'Hosea', 12, 7, 'خو څښتن وایي: «د اسراییلو خلک هغه سوداګران دي چې د غلطو ترازوګانو څخه کار اخلي او دا خوښوي چې د خلکو سره ټګي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_7.mp3', '', 1761754199, 1761754199),
(42378, 'Hosea 12:8', 'Hosea', 12, 8, 'هغوی په غرور سره وایي: ‹مونږ شتمن یو او د ښه قسمت خاوندان یو. هېڅوک مونږ په دې نه شي ملامتولی چې مونږ په بې‌ایمانۍ سره دولتمن شوي یو.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_8.mp3', '', 1761754199, 1761754199),
(42379, 'Hosea 12:9', 'Hosea', 12, 9, 'خو زه ستاسو څښتن خدای یم چې تاسو یې د مصر نه راوویستلئ. زه به تاسو مجبور کړم چې یوځل بیا په خېمو کې واوسېږئ، لکه څنګه چې تاسو په دښته کې اوسېدلئ او ستاسو سره مې لیدنه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_9.mp3', '', 1761754199, 1761754199),
(42380, 'Hosea 12:10', 'Hosea', 12, 10, 'ما د پیغمبرانو سره خبرې وکړې، دا زه وم چې هغوی ته مې ډېرې رویاګانې ورکړې او د پیغمبرانو په وسیله مې خپلو خلکو ته په مثالونو کې خبرداری ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_10.mp3', '', 1761754199, 1761754199),
(42381, 'Hosea 12:11', 'Hosea', 12, 11, 'خو بیاهم هغوی د جلعاد په ښار کې د بتانو عبادت کوي او هرڅوک چې د هغوی عبادت کوي، هغه به تباه شي. د جلجال په ښار کې غویان قرباني کېدل، نو هلته چې کوم د قربانۍ ځایونه دي هغه به په پټیو کې د تیږو په ډېریو باندې بدل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_11.mp3', '', 1761754199, 1761754199),
(42382, 'Hosea 12:12', 'Hosea', 12, 12, 'زمونږ نیکه یعقوب سوریې ته وتښتېد. هلته د ښځې د پیدا کولو دپاره مجبور ؤ چې کار وکړي او پسونه وڅروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_12.mp3', '', 1761754199, 1761754199),
(42383, 'Hosea 12:13', 'Hosea', 12, 13, 'څښتن یو پیغمبر ولېږه چې د اسراییلو خلک په مصر کې د غلامۍ نه خلاص کړي او په هغوی باندې پام وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_13.mp3', '', 1761754199, 1761754199),
(42384, 'Hosea 12:14', 'Hosea', 12, 14, 'د اسراییلو خلکو څښتن ډېر سخت په قهر کړ. هغوی د خپلو جرمونو له امله د مرګ لایق دي. نو څښتن به هغوی ته د خپل سپکاوي په خاطر سزا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea12_verse_14.mp3', '', 1761754199, 1761754199),
