(42392, 'Numbers 9:10', 'Numbers', 9, 10, 'د اسراییلو خلکو ته ووایي: «که چېرې تاسو یا ستاسو د اولادې څخه څوک په مړي باندې په لګېدلو سره ناپاک شوی وي او یا په لېرې سفر کې وي، خو وغواړي چې د فسحې اختر ولمانځي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_10.mp3', '', 1761754199, 1761754199),
(42393, 'Numbers 9:11', 'Numbers', 9, 11, 'نو هغه دې د دوهمې میاشتې د څوارلسمې ورځې په ماښام یعنې یوه میاشت وروسته ولمانځي. هغه دې د فسحې وری د فطیرې ډوډۍ او ترخو بوټو سره وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_11.mp3', '', 1761754199, 1761754199),
(42394, 'Numbers 9:12', 'Numbers', 9, 12, 'د هغه څخه دې هېڅ شی تر سهاره پورې نه پرېږدي او د حیوان هېڅ یو هډوکی دې نه ماتوي. کله چې هغه د فسحې اختر لمانځي، باید د دغو ټولو مقرراتو څخه پیروي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_12.mp3', '', 1761754199, 1761754199),
(42395, 'Numbers 9:13', 'Numbers', 9, 13, 'خو که چېرې ستاسو څخه څوک په مذهبي لحاظ پاک وي او په سفر کې نه وي او د فسحې اختر نه لمانځي، هغه باید زما د قوم څخه وشړل شي. هغه ته به سزا ورکړل شي، ځکه چې ماته یې په ټاکلي وخت نذرانې نه دي وړاندې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_13.mp3', '', 1761754199, 1761754199),
(42396, 'Numbers 9:14', 'Numbers', 9, 14, 'که چېرې هغه پردي خلک چې ستاسو په منځ کې اوسیږي وغواړي چې د فسحې اختر ولمانځي، باید د ټولو قوانینو او مقرراتو سره سم یې ولمانځي. همدا قانون په هرچا باندې که هغه اصلي اوسېدونکی وي یا پردي وي، عملي کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_14.mp3', '', 1761754199, 1761754199),
(42397, 'Numbers 9:17', 'Numbers', 9, 17, 'هرکله چې به ورېځ د خېمې څخه پورته شوه، نو اسراییلیان به روان شول. کله به چې ورېځ راښکته شوه، هغوی به خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_17.mp3', '', 1761754199, 1761754199),
(42398, 'Numbers 9:18', 'Numbers', 9, 18, 'قوم د څښتن په حکم حرکت کاوه او د هغه په حکم به یې خېمې ودرولې. تر هغه وخته پورې چې په خېمه باندې به ورېځ وه، هغوی به په هماغه کمپ کې پاتې کېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_18.mp3', '', 1761754199, 1761754199),
(42399, 'Numbers 9:19', 'Numbers', 9, 19, 'کله چې به ورېځ په خېمې باندې تر ډېره وخته پورې پاتې کېدله، هغوی د څښتن اطاعت کاوه او کډه یې نه کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_19.mp3', '', 1761754199, 1761754199),
(42400, 'Numbers 9:20', 'Numbers', 9, 20, 'کله کله به ورېځ په خېمې باندې یوازې د یو څو ورځو دپاره پاتې کېدله، په هر حال کې به هغوی د څښتن د حکم سره سم په کمپ کې پاتې کېدل یا به یې کډه کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_20.mp3', '', 1761754199, 1761754199),
(42401, 'Numbers 9:21', 'Numbers', 9, 21, 'کله کله ورېځ یوازې د ماښام څخه تر سهاره پورې پاتې کېدله، څنګه به چې ورېځ پورته شوه، هغوی به کډه کوله. هرکله چې ورېځ پورته کېدله، هغوی کډه کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_21.mp3', '', 1761754199, 1761754199),
(42402, 'Numbers 9:22', 'Numbers', 9, 22, 'که دا به دوه ورځې، یوه میاشت یا به ډېره موده وه، ترڅو چې په خېمې باندې به ورېځ وه هغوی کډه نه کوله. خو کله چې ورېځ پورته کېدله، هغوی به کډه کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_22.mp3', '', 1761754199, 1761754199),
(42403, 'Numbers 9:23', 'Numbers', 9, 23, 'هغوی به د څښتن په حکم خېمې ودرولې او د هغه په حکم به یې حرکت کاوه. هغوی د څښتن د حکمونو څخه چې د موسی په وسیله یې کول، اطاعت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers9_verse_23.mp3', '', 1761754199, 1761754199),
(42404, 'Ezekiel 29:1', 'Ezekiel', 29, 1, 'زمونږ د جلاوطنۍ په لسم کال د لسمې میاشتې په دولسمه ورځ څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_1.mp3', '', 1761754199, 1761754199),
(42405, 'Ezekiel 29:2', 'Ezekiel', 29, 2, '«ای فاني انسانه، د مصر پاچا فرعون ته مخ ورواړوه. د هغه او د مصر د ټولو خلکو په خلاف نبوت وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_2.mp3', '', 1761754199, 1761754199),
(42406, 'Ezekiel 29:3', 'Ezekiel', 29, 3, 'هغه ته ووایه چې څښتن تعالی داسې وایي: ‹ای د مصر پاچا فرعونه، زه ستا په خلاف یم، ته داسې یوه لویه بلا یې چې په سیندونو کې پروت یې. ته وایې چې د نیل سیند زما دی او ما د خپل ځان دپاره جوړ کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_3.mp3', '', 1761754199, 1761754199),
(42407, 'Ezekiel 29:4', 'Ezekiel', 29, 4, 'زه به ستا په ژامه کې چنګکونه واچوم او ستا د سیندونو ماهیان به تا پورې کلک ونښلوم. بیا به تا د هغو ماهیانو سره چې درپورې نښتي دي، ستا د سیندونو نه راوباسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_4.mp3', '', 1761754199, 1761754199),
(42408, 'Ezekiel 29:5', 'Ezekiel', 29, 5, 'زه به تا او هغه ټول ماهیان په دښته کې وغورځوم او هلته به یې پرېږدم. ستا مړی به په ځمکه باندې پروت وي او ښخ به نه شي. زه به هغه د حیواناتو او مرغانو د خوراک کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_5.mp3', '', 1761754199, 1761754199),
(42409, 'Ezekiel 29:6', 'Ezekiel', 29, 6, 'بیا به د مصر ټول خلک پوه شي چې زه څښتن یم.› څښتن وایي: ‹اسراییلیانو په مصریانو باندې تکیه کوله چې ملاتړ به یې وکړي، خو تاسو د یوې کمزورې لوخې څخه جوړه شوې امسا په شان وئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_6.mp3', '', 1761754199, 1761754199),
(42410, 'Ezekiel 29:7', 'Ezekiel', 29, 7, 'کله چې هغوی درباندې تکیه وکړه، نو ته ماته شوې، د هغوی اوږې دې سورۍ کړې او د هغوی ملاګانې دې ژوبل کړې.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_7.mp3', '', 1761754199, 1761754199);